import { z } from "zod";

export const projectPermissionSchema = z.enum(["read", "write"]);
export const apiPermissionsSchema = z.object({
	projects: z.array(projectPermissionSchema).default([]),
});

export type ApiPermissions = z.infer<typeof apiPermissionsSchema>;
export type ApiPermissionRequirement = {
	[K in keyof ApiPermissions]?: ApiPermissions[K];
};

export const PROJECT_PERMISSION_OPTIONS = [
	{ value: "read", label: "Read projects" },
	{ value: "write", label: "Create and change projects" },
] as const;

export function hasRequiredPermissions(
	actual: ApiPermissions,
	required: ApiPermissionRequirement,
) {
	return Object.entries(required).every(([resource, actions]) => {
		const granted = actual[resource as keyof ApiPermissions] ?? [];
		return actions?.every((action) => granted.includes(action)) ?? true;
	});
}

import { auth } from "#/lib/auth";
import {
	type ApiPermissionRequirement,
	type ApiPermissions,
	apiPermissionsSchema,
	hasRequiredPermissions,
} from "./permissions";
import { ApiHttpError } from "./responses";

export type ApiPrincipal = {
	type: "user";
	userId: string;
	keyId: string;
	permissions: ApiPermissions;
};

export async function requireApiKey(
	request: Request,
	required: ApiPermissionRequirement,
): Promise<ApiPrincipal> {
	const rawKey = request.headers.get("x-api-key")?.trim();
	if (!rawKey) {
		throw new ApiHttpError(
			401,
			"unauthorized",
			"A valid X-API-Key header is required.",
		);
	}

	const result = await auth.api.verifyApiKey({ body: { key: rawKey } });
	if (!result.valid || !result.key) {
		if (result.error?.code === "RATE_LIMITED") {
			throw new ApiHttpError(
				429,
				"rate_limited",
				"The API key rate limit was exceeded.",
			);
		}
		throw new ApiHttpError(
			401,
			"unauthorized",
			"The API key is invalid or inactive.",
		);
	}

	const parsedPermissions = apiPermissionsSchema.safeParse(
		result.key.permissions ?? {},
	);
	const permissions = parsedPermissions.success
		? parsedPermissions.data
		: apiPermissionsSchema.parse({});
	if (!hasRequiredPermissions(permissions, required)) {
		throw new ApiHttpError(
			403,
			"forbidden",
			"The API key lacks the required permission.",
		);
	}

	return {
		type: "user",
		userId: result.key.referenceId,
		keyId: result.key.id,
		permissions,
	};
}

